class Solution {
public:
    vector<string> removeComments(vector<string>& source) {
        bool inBlock = false;
        vector<string> ans;
        string newline = "";

        for (const string& line : source) {
            int n = line.size();
            for (int i = 0; i < n; i++) {
                if (!inBlock && i + 1 < n && line[i] == '/' && line[i + 1] == '*') {
                    inBlock = true;
                    i++;
                } else if (inBlock && i + 1 < n && line[i] == '*' && line[i + 1] == '/') {
                    inBlock = false;
                    i++;
                } else if (!inBlock && i + 1 < n && line[i] == '/' && line[i + 1] == '/') {
                    break;
                } else if (!inBlock) {
                    newline += line[i];
                }
            }
            if (!inBlock && !newline.empty()) {
                ans.push_back(newline);
                newline = "";
            }
        }
        return ans;
    }
};

class Solution {
    public List<String> removeComments(String[] source) {
        boolean inBlock = false;
        List<String> ans = new ArrayList<>();
        StringBuilder newline = new StringBuilder();

        for (String line : source) {
            int n = line.length();
            for (int i = 0; i < n; i++) {
                if (!inBlock && i + 1 < n && line.charAt(i) == '/' && line.charAt(i + 1) == '*') {
                    inBlock = true;
                    i++;
                } else if (inBlock && i + 1 < n && line.charAt(i) == '*' && line.charAt(i + 1) == '/') {
                    inBlock = false;
                    i++;
                } else if (!inBlock && i + 1 < n && line.charAt(i) == '/' && line.charAt(i + 1) == '/') {
                    break;
                } else if (!inBlock) {
                    newline.append(line.charAt(i));
                }
            }
            if (!inBlock && newline.length() > 0) {
                ans.add(newline.toString());
                newline.setLength(0);
            }
        }
        return ans;
    }
}

